/**
 * 실제 data/*.json 을 읽어 검증한 결과.
 * 번들러(Vite/vitest)가 JSON 을 그대로 import 한다.
 */
import blocksJson from '../../../../data/blocks.json';
import combatJson from '../../../../data/combat.json';
import petNamesJson from '../../../../data/pet-names.json';
import bannedWordsJson from '../../../../data/banned-words.json';
import buildingsJson from '../../../../data/buildings.json';
import bossesJson from '../../../../data/bosses.json';
import mobsJson from '../../../../data/mobs.json';
import dragonsJson from '../../../../data/dragons.json';
import expeditionsJson from '../../../../data/expeditions.json';
import familyRulesJson from '../../../../data/family-rules.json';
import phrasesJson from '../../../../data/phrases.json';
import potionsJson from '../../../../data/potions.json';
import recipesJson from '../../../../data/recipes.json';
import redstoneJson from '../../../../data/redstone.json';
import giftsJson from '../../../../data/gifts.json';
import starterKitJson from '../../../../data/starter-kit.json';
import toolsJson from '../../../../data/tools.json';
import foodJson from '../../../../data/food.json';
import fishingJson from '../../../../data/fishing.json';
import tradesJson from '../../../../data/trades.json';
import enchantsJson from '../../../../data/enchants.json';
import xpJson from '../../../../data/xp.json';
import villagerTalkJson from '../../../../data/villager-talk.json';
import { parseBlocks } from './blocks';
import { parseCombat } from './combat';
import { parsePetNames } from './petNames';
import { parseVillagerTalk } from './villagerTalk';
import { parseBannedWords } from './bannedWords';
import { parseBuildings } from './buildings';
import { parseMobs } from './mobs';
import { parseRaid } from './raid';
import { dragonEggBlocks, eggItem, eggRecipes, parseDragons } from './dragons';
import { parseExpeditions } from './expeditions';
import { parseFamilyRules } from './family';
import { buildItemNames } from './items';
import { parsePhrases } from './phrases';
import { RecipeRegistry, parseRecipes } from './recipes';
import { parsePotions } from './potions';
import { parseRedstone } from './redstone';
import { parseGifts } from './gifts';
import { parseStarterKit } from './starterKit';
import { parseTools } from './tools';
import { parseFood } from './food';
import { parseFishing } from './fishing';
import { parseTrades } from './trades';
import { parseEnchants } from './enchants';
import { parseXp } from './xp';

/** 드래곤 16종 (M6-2, 아들 설계) */
export const DRAGONS = parseDragons(dragonsJson);
/** 블록 = blocks.json + 드래곤마다의 알 블록 16개 (#249, 바닥에 놓은 알) */
export const BLOCKS = parseBlocks({ ...blocksJson, blocks: [...blocksJson.blocks, ...dragonEggBlocks(DRAGONS)] });
/** 마을 건물 (M6-6) — 비용은 공유 창고에서 */
export const BUILDINGS = parseBuildings(buildingsJson);
export const POTIONS = parsePotions(potionsJson);
export const REDSTONE = parseRedstone(redstoneJson);
export const EXPEDITIONS = parseExpeditions(expeditionsJson);
/** 펫 이름 목록 (M8-1 4차, pet-names.json, #109) */
export const PET_NAMES = parsePetNames(petNamesJson);
/** 주민 대화 (#172) */
export const VILLAGER_TALK = parseVillagerTalk(villagerTalkJson);
/** 이름 금칙어 (M9-4, banned-words.json, #152) */
export const BANNED_WORDS = parseBannedWords(bannedWordsJson);
/** 전투 장비 — 갑옷·방패·활·화살 (M8-2, combat.json). 제작법도 여기서 나온다 */
export const COMBAT = parseCombat(combatJson);
/** 레시피 + 드래곤 알 레시피 16개(제작대) + 전투 장비 레시피 25개 */
export const RECIPES = new RecipeRegistry([...parseRecipes(recipesJson).defs, ...eggRecipes(DRAGONS), ...COMBAT.recipes]);
export const PHRASES = parsePhrases(phrasesJson);
/** 가족 시간 규칙 (M5, 아들 값: 평일 20·주말 30·보너스 5) */
export const FAMILY_RULES = parseFamilyRules(familyRulesJson);
/** 곡괭이 등급 (아들 2026-09-20) */
export const TOOLS = parseTools(toolsJson);
/** 먹을 것 (#186) */
export const FOOD = parseFood(foodJson);
/** 낚시 (2026-11-06) */
export const FISHING = parseFishing(fishingJson);
/** 주민 거래 (#225) */
export const TRADES = parseTrades(tradesJson);
/** 인챈트 (#231) */
export const ENCHANTS = parseEnchants(enchantsJson);
/** 경험치 규칙 (M6-1, 마인크래프트 값 + 우리 것) */
export const XP = parseXp(xpJson);
/** 원정 밤의 몹 — 좀비·크리퍼 (M7-2). 드롭·이름은 mobs.json, 경험치는 xp.json */
export const MOBS = parseMobs(mobsJson, XP.mobs, 'data/mobs.json', bossesJson);
/** 마을 방어전 규칙 (bosses.json raids, M7-5) */
export const RAIDS = parseRaid(bossesJson);
/** 처음 들어올 때 한 번 받는 것 (#67) */
export const STARTER_KIT = parseStarterKit(starterKitJson);
/** 아빠가 모두에게 한 번씩 주는 선물 (#79) */
export const GIFTS = parseGifts(giftsJson);
/** 아이템 id → 한국어 이름 (블록 아닌 것). 블록은 BLOCKS 에서 */
export const ITEM_NAMES = buildItemNames({ recipes: recipesJson, dragons: dragonsJson, potions: potionsJson, extra: COMBAT.itemNames });
for (const d of DRAGONS.list) ITEM_NAMES.set(eggItem(d.id), `${d.name} 알`);
for (const e of ENCHANTS.list) ITEM_NAMES.set('ench.' + e.id, e.name); // 인챈트 이름 (#231): itemName 이 '철 검 ✨날카로움 II' 로 쓴다
ITEM_NAMES.set('lapis', ITEM_NAMES.get('lapis') ?? '청금석');
